/**
 * Small helper: run a traverser in parallel (OpenMP) over its outermost
 * dimension while still using Noarr's for_each for the inner dimensions.
 *
 * If OpenMP is not enabled, this just calls trav.for_each(fun) serially.
 *
 * The parallelization strategy is:
 *   - the outer #pragma omp parallel for splits the *outermost* Noarr
 *     dimension handled by `trav`
 *   - each iteration gets a smaller traverser (`inner_trav`) with that
 *     dimension fixed
 *   - `inner_trav.for_each(fun)` then walks the remaining dimensions
 */
template<typename Traverser, typename Func>
inline void parallel_for_each_traverser(const Traverser &trav, const Func &fun) {
#ifdef _OPENMP
#pragma omp parallel for schedule(static)
	for (auto inner_trav : trav) {
		inner_trav.for_each(fun);
	}
#else
	trav.for_each(fun);
#endif
}

// Array initialization
void init_array(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	// Dimensions
	auto nx = ex | get_length<'i'>();
	auto ny = ex | get_length<'j'>();

	// Initialize fict[t] = t
	parallel_for_each_traverser(traverser(fict), [=](auto state) {
		auto t = get_index<'t'>(state);
		fict[state] = static_cast<num_t>(t);
	});

	// Initialize ex, ey, hz over the spatial grid
	parallel_for_each_traverser(traverser(ex, ey, hz), [=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		ex[state] = (static_cast<num_t>(i) * (j + 1)) / static_cast<num_t>(nx);
		ey[state] = (static_cast<num_t>(i) * (j + 2)) / static_cast<num_t>(ny);
		hz[state] = (static_cast<num_t>(i) * (j + 3)) / static_cast<num_t>(nx);
	});
}

// Main computational kernel
// - preserves the original numerical scheme
// - improves locality by fusing the ex/ey updates into one spatial sweep
// - exploits parallelism in space via OpenMP over the outer Noarr dimension
[[gnu::flatten, gnu::noinline]]
void kernel_fdtd_2d(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	auto nx = ex | get_length<'i'>();
	auto ny = ex | get_length<'j'>();

	const num_t half      = SCALAR_VAL(0.5);
	const num_t coeff_hz  = SCALAR_VAL(0.7);

	// BLAS-like params in original:
	// Time-stepping FDTD on a 2D grid

#pragma scop
	// Outer time loop over t (must remain sequential due to time dependencies)
	traverser(fict, ex, ey, hz).template for_dims<'t'>([=](auto trav_t) {
		// State with only the current time index
		auto t_state = trav_t.state();
		const num_t boundary_val = fict[t_state]; // fict[t] is constant over i,j in this timestep

		// -------------------------------------------------------------------
		// Combined update of ey and ex for the current time step:
		//
		// Original code:
		//   ey[0][j] = fict[t]                           for j = 0..ny-1
		//   ey[i][j] -= 0.5 * (hz[i][j] - hz[i-1][j])   for i = 1..nx-1, j = 0..ny-1
		//   ex[i][j] -= 0.5 * (hz[i][j] - hz[i][j-1])   for i = 0..nx-1, j = 1..ny-1
		//
		// These three loops are pointwise in (i,j) and only read hz.
		// There are no data dependencies between different grid points in
		// this phase, so we can fuse them safely:
		//
		//   for all i,j:
		//     if i == 0: ey = fict[t]
		//     else      : ey -= 0.5 * (hz[i][j] - hz[i-1][j])
		//
		//     if j > 0  : ex -= 0.5 * (hz[i][j] - hz[i][j-1])
		//
		// This preserves the numerical result exactly, but reduces the
		// number of traversals over the grid and gives the compiler more
		// freedom to optimize and vectorize.
		// -------------------------------------------------------------------

		// We hoist 'i' to be the outermost dimension to make the outer
		// OpenMP parallel-for split the grid into (contiguous) rows.
		auto trav_space = trav_t.order(noarr::hoist<'i'>());

		parallel_for_each_traverser(trav_space, [=](auto state) {
			auto [i, j] = get_indices<'i', 'j'>(state);

			// ey boundary at i == 0, interior ey otherwise
			if (i == 0) {
				// ey[0][j] = fict[t]
				ey[state] = boundary_val;
			} else {
				// ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j])
				auto state_im1j = state - idx<'i'>(1);
				ey[state] -= half * (hz[state] - hz[state_im1j]);
			}

			// ex interior in j (j >= 1); j == 0 remains unchanged
			if (j > 0) {
				// ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1])
				auto state_ijm1 = state - idx<'j'>(1);
				ex[state] -= half * (hz[state] - hz[state_ijm1]);
			}
		});

		// -------------------------------------------------------------------
		// hz update (remains structurally identical to original code):
		//
		//   hz[i][j] = hz[i][j] - 0.7 * (ex[i][j+1] - ex[i][j]
		//                               + ey[i+1][j] - ey[i][j])
		//   for i = 0..nx-2, j = 0..ny-2
		//
		// This uses the newly updated ex and ey, so it must come *after*
		// the fused ex/ey phase. The update is pointwise over (i,j), so we
		// can parallelize it as well.
		// -------------------------------------------------------------------
		auto trav_hz = trav_t.order(
			noarr::slice<'i'>(0, nx - 1) ^ // i in [0, nx-2]
			noarr::slice<'j'>(0, ny - 1)   // j in [0, ny-2]
		);

		parallel_for_each_traverser(trav_hz, [=](auto state) {
			auto state_i_jp1 = state + idx<'j'>(1);
			auto state_ip1_j = state + idx<'i'>(1);

			hz[state] -= coeff_hz *
				((ex[state_i_jp1] - ex[state]) +
				 (ey[state_ip1_j] - ey[state]));
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

