#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>
#include <noarr/structures/interop/traverser_iter.hpp> // for range-based traverser iteration (OpenMP-friendly)

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "fdtd-2d.hpp"

using num_t = DATA_TYPE;

namespace {

// Convenience proto-structures for dimensions
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto t_vec = noarr::vector<'t'>();

struct tuning {
	// 2D fields: i x j, with j the inner (contiguous) dimension
	DEFINE_PROTO_STRUCT(field_layout, j_vec ^ i_vec);
	// 1D fictitious array over time
	DEFINE_PROTO_STRUCT(fict_layout, t_vec);
} tuning;

// -----------------------------------------------------------------------------
// Small helper: parallel for_each over the outermost dimension of a traverser
// -----------------------------------------------------------------------------
//
// This mirrors the pattern from the Noarr docs:
//   #pragma omp parallel for
//   for (auto trav_inner : trav)
//       trav_inner.for_each(f);
//
// If OpenMP is not enabled, the pragma is ignored and execution stays serial.
template<typename Traverser, typename Func>
inline void omp_trav_for_each(const Traverser &trav, const Func &f) {
#pragma omp parallel for
	for (auto inner : trav) {
		inner.for_each(f);
	}
}

// -----------------------------------------------------------------------------
// Array initialization
// -----------------------------------------------------------------------------
void init_array(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	// Initialize fict[t] = t
	traverser(fict).for_each([=](auto state) {
		auto t = get_index<'t'>(state);
		fict[state] = static_cast<num_t>(t);
	});

	// Dimensions
	auto nx = ex | get_length<'i'>();
	auto ny = ex | get_length<'j'>();

	// Initialize ex, ey, hz
	traverser(ex, ey, hz).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		ex[state] = (static_cast<num_t>(i) * (static_cast<num_t>(j) + num_t(1))) / static_cast<num_t>(nx);
		ey[state] = (static_cast<num_t>(i) * (static_cast<num_t>(j) + num_t(2))) / static_cast<num_t>(ny);
		hz[state] = (static_cast<num_t>(i) * (static_cast<num_t>(j) + num_t(3))) / static_cast<num_t>(nx);
	});
}

// -----------------------------------------------------------------------------
// Main computational kernel
// -----------------------------------------------------------------------------
//
// Optimizations over the original version:
//  - precompute scalar constants (0.5, 0.7)
//  - fuse the interior ex/ey updates into a single pass over i>=1, j>=1
//    so hz[i][j] is loaded once per cell and reused for both updates
//  - keep separate thin boundary loops to preserve semantics exactly
//  - use omp_trav_for_each (OpenMP) to parallelize all 1D/2D spatial traversals
//
// All traversals are still expressed via Noarr traversers, and states are used
// for indexing as required.
//
[[gnu::flatten, gnu::noinline]]
void kernel_fdtd_2d(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

	auto nx = ex | get_length<'i'>();
	auto ny = ex | get_length<'j'>();

	const num_t half = SCALAR_VAL(0.5);
	const num_t c07  = SCALAR_VAL(0.7);

#pragma scop
	// Outer time loop over t
	traverser(fict, ex, ey, hz).template for_dims<'t'>([=](auto trav_t) {
		// State with only the current time index
		auto t_state = trav_t.state();

		// ---------------------------------------------------------------------
		// 1) ey[0][j] = fict[t] for all j
		//    Pure 1D update along the j dimension.
		// ---------------------------------------------------------------------
		omp_trav_for_each(
			trav_t.order(noarr::fix<'i'>(0)),
			[=](auto state) {
				// state has i = 0 and varying j; t is taken from t_state
				ey[state] = fict[t_state];
			}
		);

		// ---------------------------------------------------------------------
		// 2) ey[i][0] = ey[i][0] - 0.5 * (hz[i][0] - hz[i-1][0])
		//    for i = 1..nx-1, j = 0
		//    This covers the first column (j = 0) except row 0 (handled above).
		// ---------------------------------------------------------------------
		if (nx > 1) {
			omp_trav_for_each(
				trav_t.order(noarr::slice<'i'>(1, nx - 1) ^ noarr::fix<'j'>(0)),
				[=](auto state) {
					// state: i in [1, nx-1], j = 0
					auto state_im1j = state - noarr::idx<'i'>(1);

					ey[state] -= half * (hz[state] - hz[state_im1j]);
				}
			);
		}

		// ---------------------------------------------------------------------
		// 3) Interior ex & ey updates, fused:
		//    ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j])
		//    ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1])
		//    for i = 1..nx-1, j = 1..ny-1
		//
		//    This is the main 2D interior; we do a single pass to reuse hz[i][j]
		//    instead of loading it once in the ey loop and once in the ex loop.
		// ---------------------------------------------------------------------
		if (nx > 1 && ny > 1) {
			omp_trav_for_each(
				trav_t.order(noarr::slice<'i'>(1, nx - 1) ^ noarr::slice<'j'>(1, ny - 1)),
				[=](auto state) {
					// state: i in [1, nx-1], j in [1, ny-1]
					auto state_im1j = state - noarr::idx<'i'>(1);
					auto state_ijm1 = state - noarr::idx<'j'>(1);

					const num_t hz_ij   = hz[state];
					const num_t hz_im1j = hz[state_im1j];
					const num_t hz_ijm1 = hz[state_ijm1];

					ey[state] -= half * (hz_ij - hz_im1j);
					ex[state] -= half * (hz_ij - hz_ijm1);
				}
			);
		}

		// ---------------------------------------------------------------------
		// 4) ex[0][j] = ex[0][j] - 0.5 * (hz[0][j] - hz[0][j-1])
		//    for i = 0, j = 1..ny-1
		//
		//    This is the remaining part of the original ex loop: the first row,
		//    excluding j = 0. (j = 0 is not updated by the original kernel.)
		// ---------------------------------------------------------------------
		if (ny > 1) {
			omp_trav_for_each(
				trav_t.order(noarr::fix<'i'>(0) ^ noarr::slice<'j'>(1, ny - 1)),
				[=](auto state) {
					// state: i = 0, j in [1, ny-1]
					auto state_ijm1 = state - noarr::idx<'j'>(1);

					ex[state] -= half * (hz[state] - hz[state_ijm1]);
				}
			);
		}

		// ---------------------------------------------------------------------
		// 5) hz[i][j] update:
		//    hz[i][j] = hz[i][j] - 0.7 * (ex[i][j+1] - ex[i][j]
		//                                + ey[i+1][j] - ey[i][j])
		//    for i = 0..nx-2, j = 0..ny-2
		//
		//    This still matches the original domain: we slice i in [0,nx-2]
		//    and j in [0,ny-2]. The traverser guarantees the neighbor indices
		//    (i+1, j) and (i, j+1) are valid.
		// ---------------------------------------------------------------------
		if (nx > 1 && ny > 1) {
			omp_trav_for_each(
				trav_t.order(
					noarr::slice<'i'>(0, nx - 1) ^
					noarr::slice<'j'>(0, ny - 1)
				),
				[=](auto state) {
					// state: i in [0, nx-2], j in [0, ny-2]
					auto state_i_jp1 = state + noarr::idx<'j'>(1);
					auto state_ip1_j = state + noarr::idx<'i'>(1);

					const num_t ex_diff = ex[state_i_jp1] - ex[state];
					const num_t ey_diff = ey[state_ip1_j] - ey[state];

					hz[state] -= c07 * (ex_diff + ey_diff);
				}
			);
		}
	});
#pragma endscop
