	// Time-stepping FDTD on a 2D grid

#pragma scop
	// Outer time loop over t: traverse fict, ex, ey, hz together,
	// but only fict has dimension 't'. The traverser will add 't'
	// to the state, which ex/ey/hz simply ignore.
	traverser(fict, ex, ey, hz).template for_dims<'t'>([=](auto trav_t) {
		// State with only the current time index
		auto t_state = trav_t.state();
		// Cache fict[t] once per time-step instead of reloading in every j
		const num_t fict_t = fict[t_state];

		// -----------------------------------------------------------------
		// 1) ey[0][j] = fict[t] for all j
		//    Single row, j is the contiguous dimension.
		// -----------------------------------------------------------------
		trav_t
			.order(noarr::fix<'i'>(0))
			.for_each([=](auto state) {
				// state: i = 0, all j; still contains 't' but ey ignores it
				ey[state] = fict_t;
			});

		// -----------------------------------------------------------------
		// 2) ey[i][j] = ey[i][j] - 0.5 * (hz[i][j] - hz[i-1][j])
		//    for i = 1..nx-1, j = 0..ny-1
		//
		//    We tile along j (the inner, contiguous dimension) using
		//    into_blocks_static. This gives the compiler shorter, regular
		//    inner loops that are friendlier to SIMD without changing the
		//    mathematical result. into_blocks_static takes care of "border"
		//    elements when ny-1 is not a multiple of EY_J_BLOCK.
		// -----------------------------------------------------------------
		auto trav_ey = trav_t.order(noarr::slice<'i'>(1, nx_minus_1));

		auto trav_ey_tiled = trav_ey.order(
			noarr::into_blocks_static<'j', 'b', 'J', 'j'>(EY_J_BLOCK) ^
			noarr::hoist<'J'>() // outer loop over j-blocks, inner over j
		);

		trav_ey_tiled.for_each([=](auto state) {
			// state: i in [1, nx-1], j in [0, ny-1]
			auto state_im1j = state - noarr::idx<'i'>(1);

			ey[state] = ey[state]
			            - half * (hz[state] - hz[state_im1j]);
		});

		// -----------------------------------------------------------------
		// 3) ex[i][j] = ex[i][j] - 0.5 * (hz[i][j] - hz[i][j-1])
		//    for i = 0..nx-1, j = 1..ny-1
		//
		//    Same idea: keep j contiguous and apply 1D tiling in j.
		// -----------------------------------------------------------------
		auto trav_ex = trav_t.order(noarr::slice<'j'>(1, ny_minus_1));

		auto trav_ex_tiled = trav_ex.order(
			noarr::into_blocks_static<'j', 'c', 'J', 'j'>(EX_J_BLOCK) ^
			noarr::hoist<'J'>()
		);

		trav_ex_tiled.for_each([=](auto state) {
			// state: i in [0, nx-1], j in [1, ny-1]
			auto state_ijm1 = state - noarr::idx<'j'>(1);

			ex[state] = ex[state]
			            - half * (hz[state] - hz[state_ijm1]);
		});

		// -----------------------------------------------------------------
		// 4) hz[i][j] = hz[i][j] - 0.7 * (ex[i][j+1] - ex[i][j]
		//                                 + ey[i+1][j] - ey[i][j])
		//    for i = 0..nx-2, j = 0..ny-2
		//
