		//    2D tiling in (i, j) to improve cache locality: each tile
		//    works on a small sub-block of ex/ey/hz.
		//
		//    into_blocks_static handles edges when dimensions are not
		//    exact multiples of the chosen block sizes. Using it via
		//    traverser::order keeps the external state in terms of the
		//    original ('i','j') indices.
		// -----------------------------------------------------------------
		auto trav_hz = trav_t.order(
			noarr::slice<'i'>(0, nx_minus_1) ^
			noarr::slice<'j'>(0, ny_minus_1)
		);

