			noarr::into_blocks_static<'i', 'd', 'I', 'i'>(HZ_I_BLOCK) ^
			noarr::into_blocks_static<'j', 'e', 'J', 'j'>(HZ_J_BLOCK) ^
			noarr::hoist<'I'>() ^ // traverse i-blocks outermost
			noarr::hoist<'J'>()   // then j-blocks
		);

