/**
 * Small helper that executes `trav.for_each(f)` in parallel using OpenMP.
 *
 * It parallelizes over the topmost dimension of the traverser. Each iteration
 * of the outer `for` receives a sub-traverser with the topmost dimension
 * fixed, and `for_each` then walks the remaining dimensions serially.
 *
 * This preserves the semantics of a plain `trav.for_each(f)` while allowing
 * the work to be distributed across threads.
 */
template<typename Trav, typename F>
inline void omp_trav_for_each(const Trav &trav, const F &f) {
#pragma omp parallel for schedule(static)
	for (auto sub_trav : trav) {
		sub_trav.for_each(f);
	}
}

// Array initialization
void init_array(auto ex, auto ey, auto hz, auto fict) {
	using namespace noarr;

